// routes is what routes_*.go files append through addRoutes; each adds its
// own paths, so a feature card owns its file and not this one.
var routes []func(*Server)

// addRoutes lets a routes_*.go file register its handlers.
func addRoutes(f func(*Server)) {
	routes = append(routes, f)
}

// New serves /healthz, the API under /api/ and the single-page app under
// /app/; / redirects to /app/. Every request goes through Auth, which names
// the session's user in the request's context.
func New(cfg Config) http.Handler {
	s := &Server{store: cfg.Store}
	owned := s.store == nil
	if owned {
		st, err := store.Open(cfg.DataDir)
		if err != nil {
			panic(err)
		}
		s.store = st
	}
	s.mux = http.NewServeMux()
	if owned {
		// New opened this store for itself and must hand the file back: a
		// test's temporary directory goes away before the process ends, and an
		// open database would leave its lock behind. Auth calls maybeCloseStore
		// for the request that matches none of this server's patterns; no route
		// names it, and the production binary passes a Store of its own and
		// never gets here.
		s.closeOwnedStore = s.store.Close
	}
	s.register("GET /healthz", http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
	}))
	for _, add := range routes {
		add(s)
	}
	// The API's defaults: an unknown path answers 404 JSON rather than fall
	// through to the single-page app, and GET /api/me answers for the user a
	// session names until the auth card registers its own handler there.
	if !s.taken("GET /api/me") {
		s.register("GET /api/me", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			requireUser(w, r)
		}))
	}
	if !s.taken("GET /api/links") {
		s.register("GET /api/links", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			if userID, ok := requireUser(w, r); ok {
				links, err := s.store.ListLinksByUser(r.Context(), userID)
				if err != nil {
					writeError(w, http.StatusInternalServerError)
					return
				}
				writeJSON(w, http.StatusOK, links)
			}
		}))
	}
	s.register("/api/", http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": "not found"})
	}))
	s.register("/app/", http.StripPrefix("/app", app()))
	s.register("GET /{$}", http.RedirectHandler("/app/", http.StatusFound))
	// The root answers the short slugs later; until then an unknown path there
	// is 404, which is what ServeMux itself gives for a request no pattern
	// covers. A feature card registers its own GET /{slug} rather than a
	// catch-all here: New names no route under / that swallows another one, so
	// ServeMux cannot panic on a clash and taken stays exact.
	return s.Auth(s.mux)
}

